def bug_fix(fix_id, *, emit_helpers=None, apply=None):
    title_ja, title_en, description_ja, description_en, explanation = DESCRIPTIONS[fix_id]
    return Fix(fix_id, title_ja, title_en, description_ja, description_en,
               emit_helpers=emit_helpers, apply=apply, explanation=explanation,
               extended_helpers=True, bug_ids=(f"msx.{fix_id}",))
